import{_ as e,c as t,o as r,ah as n}from"./chunks/framework.BxT5r71R.js";const E=JSON.parse('{"title":"希望通过BEFIRST第二张专辑向社会展现的精神","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/12_希望通过BEFIRST第二张专辑向社会展现的精神.md","filePath":"zh-cn/Management2/PART3/12_希望通过BEFIRST第二张专辑向社会展现的精神.md"}'),o={name:"zh-cn/Management2/PART3/12_希望通过BEFIRST第二张专辑向社会展现的精神.md"};function p(s,a,_,l,i,B){return r(),t("div",null,[...a[0]||(a[0]=[n('<p>► 2024年8月</p><h2 id="希望通过be-first第二张专辑向社会展现的精神" tabindex="-1">希望通过BE:FIRST第二张专辑向社会展现的精神 <a class="header-anchor" href="#希望通过be-first第二张专辑向社会展现的精神" aria-label="Permalink to &quot;希望通过BE:FIRST第二张专辑向社会展现的精神&quot;">​</a></h2><p>#领导力 #成长 #音乐制作 #BEFIRST</p><h3 id="我必须时刻意识到-自己有责任为他们创造成长机会" tabindex="-1">“我必须时刻意识到，自己有责任为他们创造成长机会” <a class="header-anchor" href="#我必须时刻意识到-自己有责任为他们创造成长机会" aria-label="Permalink to &quot;“我必须时刻意识到，自己有责任为他们创造成长机会”&quot;">​</a></h3><p><strong>BE:FIRST的第二张专辑《2:BE》于2024年8月28日发行。专辑发行前先行上线的主打歌《Blissful》，登上8月21日公布的Billboard JAPAN综合歌曲榜JAPAN Hot 100榜首，并在各类音乐榜单中斩获185项第一。</strong></p><p><strong>距离首张专辑《BE:1》发行，恰好过去了2年。这期间，BE:FIRST首次在东京、大阪举行巨蛋演出，大获成功，如今已稳居日本代表性男子组合之列。与此同时，从《Boom Boom Back》到《Mainstream》，再到《Masterplan》，他们作为艺人的自我意识迅速成长。大家也因此格外期待：这张堪称新篇章开端的第二张专辑，会展现他们怎样的面貌？SKY-HI又如何看待这张专辑的理念与定位？</strong></p><p>出道之初，我也考虑过今后几张专辑的方向。不过，制作首张专辑《BE:1》时，我心里有一个总体规划：用这张专辑收录的歌曲举行巨蛋演出。早在出道曲《Gifted.》发行之前，我们就已经朝着明确的目标和声音构想着手推进了。我当时想，这张专辑必须讲述一个故事：“从一无所有的零起点出发，最终站上东京巨蛋舞台。”参与这个故事的不应只有我们和粉丝，还应该有更广泛的社会公众。回过头来看，整个制作过程，就是围绕这条主线，思考当下应该歌唱什么、传达什么，再逐步明确重点。</p><p>第二张及之后的专辑也延续了这个方向。不过，无论是当时应该歌唱的内容、应该传达的事情，还是他们想做的音乐，都要符合他们当下的状态。这就需要在制作中认真面对他们的变化，始终保持灵活的思路。</p><p>说到底，与个人艺人相比，他们的人数是7倍。哪怕只是稍微换个角度，单从人数来看，也应该有7倍的表达空间。而且，只要社会不断变化，他们就始终有应该歌唱的内容。尤其在如今这个很难称得上和平的世界里，我觉得，应该唱的、能够唱的、大家需要的音乐，以及单纯觉得做起来会很开心的音乐，都还有很多。</p><p>在这样的背景下，第二张专辑《2:BE》有一个重要主题：如今，社会上彼此拖后腿、排挤他人的风气很重，我们希望向社会充分展现BE:FIRST自然而然具备的精神——彼此赞美、相互肯定。娱乐圈经常有人说：“组合只要能顺利开展工作，成员之间不一定非要关系好。”但我一直很不认同这句话。既然特意组建一个组合，就应该有非这些伙伴不可的理由：“正因为是这些成员、这个组合，我们才想一起做下去。”组合内部也应该有这样的氛围。</p><p>稍微岔开一下话题，我一直觉得，每逢值得庆祝的事，都一定要好好庆祝。拿了什么第一，或者达成了某个目标，就马上庆祝。因为这样更开心，也有助于肯定自己、肯定他人。BE:FIRST举行巨蛋演出之后，我重视的是大家彼此赞美、相互肯定的氛围。不要说“哪里哪里，没什么了不起的，我们才刚起步”，而是说：“一路走到这里，我们真够努力的，做到了！”“我们真了不起！”总之，我们要传达自我关爱的精神：不仅肯定自己，也肯定他人。在我看来，这是世上最可贵的价值观。这就是以《Blissful》为主打歌的《2:BE》的存在意义。</p><h3 id="全体成员参与歌曲制作" tabindex="-1">全体成员参与歌曲制作 <a class="header-anchor" href="#全体成员参与歌曲制作" aria-label="Permalink to &quot;全体成员参与歌曲制作&quot;">​</a></h3><p><strong>这张专辑以《Slogan》开篇，高声宣告BE:FIRST一路走来的历程，以及如今应有的模样。而初听时，出乎我意料的是第13首《BE:0-interlude-》。意想不到的展开，加上饱含情感的声音，听得我心潮涌动。</strong></p><p>为了突出歌曲想传达的信息，在专辑中穿插间奏曲（interlude），是很常见的做法。不过，组合的专辑通常很少这样做。我很早就觉得，如果组合没法这样做，未免有些可惜。甚至有时会觉得，专辑为什么这样安排曲目顺序、一首歌为什么由这个人来唱，这些意义似乎并没有得到足够重视。紧接在《BE:0-interlude-》之后的《Glorious》，本来就是这7个人赞美自己的歌——他们从THE FIRST一路走到了今天……其实，我觉得光听歌就能明白这一点。但我们一路走来，共同经历了这么多，也值得把这一点表达得更明确、更突出一些。我想好好呈现这段历程，所以用了THE FIRST时期的录音。</p><p>可以说，制作《Glorious》的同时，我也在构思这首间奏曲。</p><p><strong>这次，MANATO和LEO参与了主打歌《Blissful》的制作，3组成员也分别参与了各自小组歌曲的制作。安排全体成员参与制作，是出于怎样的考虑？</strong></p><p>谁也不知道，什么会成为一个人成长的契机。像他们这样从事音乐工作的人，想亲自创作音乐，或者希望学会创作，当然是再自然不过的事。不过，我们也必须坚持专业标准，不能因为参与创作的是成员，就迁就他们，什么作品都拿出来发行。我觉得，这次也确实做出了水准很高的歌曲。</p><p>我必须时刻意识到，自己有责任为他们创造成长机会。有了这些经历，今后或许还能为某位成员创造机会，进一步发展他独特的艺术个性。而且，这些经历带来的启发并不限于创作。参与歌曲制作，他们可能会更加喜欢音乐，听辨和鉴赏能力也随之提高，进而唱得更好。了解制作过程之后，我们也能更深入地交流对歌曲的看法。</p><p>以前和BE:FIRST聊起“我们想做这样的歌”时，交流就不止于一句“很酷”，而是能具体谈到：“上次尝试了2000年前后的那种风格，下次是不是可以试试2010年左右的感觉，配上这样的律动？”他们有一点很好：只要听过歌曲，就能理解我们背后的意图。我期待，随着这样的制作经历不断积累，他们对音乐的理解也会更加系统、更加深入。</p><p>所以，成员参与制作，确实只有好处。唯一辛苦的地方，就是费时间。如果我一个人来做，大多数制作工作2～3个小时就能完成；但一起做，至少需要2倍的时间，有时大家还得各自带回去继续做。要说辛苦，也确实辛苦。毕竟，我的2～3个小时可是很贵的（笑）。不过，考虑到他们的未来，这些时间和经历都无可替代。而且，有了这些经历，他们今后想做什么、应该做什么，也会越来越明确。该做怎样的歌曲、与哪位创作者合作、怎样合作，自然也会逐渐清晰。音乐人之间的沟通越准确，作品的完成度也会越高。</p><p>我必须让大家——至少是音乐行业里的大家——形成这样的认识：“BMSG旗下每一位艺人，包括组合中的每一位成员，音乐水准和音乐意识都有保障。”这是我的使命。他们只管按自己的意愿，做自己喜欢的事。我的工作，就是为他们开路、铺路，确保这样做能成为正确的选择。身处这个位置，我多少也能看见他们未来的样子。一想到几年后的他们，就觉得有无限可能。很期待（笑）。</p>',21)])])}const d=e(o,[["render",p]]);export{E as __pageData,d as default};
